hookGear:
const rotY = j.tx.rotate(j.axis.Y, deg(90)), rotXn = j.tx.rotate(j.axis.X, deg(-90))
const mv = (x, y, z) => j.tx.move(x, y, z)
const cylX = (rr, x0, x1, y = 0, z = 0) => j.cyl(rr, x1 - x0).moved(rotY).moved(mv(x0, y, z))
const cylY = (rr, y0, y1, x = 0, z = 0) => j.cyl(rr, y1 - y0).moved(rotXn).moved(mv(x, y0, z))
const cylZ = (rr, z0, z1, x = 0, y = 0) => j.cyl(rr, z1 - z0).moved(mv(x, y, z0))
const tubeZ = (ro, ri, z0, z1, x = 0, y = 0) => cylZ(ro, z0, z1, x, y).subtract(cylZ(ri, z0 - 1, z1 + 1, x, y))
const tubeX = (ro, ri, x0, x1, y = 0, z = 0) => cylX(ro, x0, x1, y, z).subtract(cylX(ri, x0 - 1, x1 + 1, y, z))
const boxAt = (x0, x1, y0, y1, z0, z1) => j.box(x1 - x0, y1 - y0, z1 - z0).moved(mv(x0, y0, z0))
const onYZ = x0 => j.plane.offset(j.plane.YZ, x0)
const onXY = z0 => j.plane.offset(j.plane.XY, z0)
const C = (rr, u, v) => j.region.circle(rr, { at: [u, v] })
const poly = pts => j.region.polygon(pts)
// Crossed helical ("spiral") gear: an involute transverse profile extruded with a twist.
// For shafts at 90° both gears have a 45° helix of the same hand; they share the normal module
// mn, and each has transverse module mt = mn / cos β. Addendum mn, dedendum 1.25 mn (normal).
// sign: +1 or −1 picks the hand (the twist direction about +Z as the extrusion goes up).
function spiralGear(name, z, mn, width, sign, o = {}) {
